for t in sorted(set(q['topic'] for q in qs)):
 print('\n',t)
 for q in [q for q in qs if q['topic']==t][:25]:
  print(q['id'], ' '.join('v%d:%s'%(v,','.join(('C' if s['correct'] else ('H'+s['answer'] if s['score']>.6 else 'x')) for s in q['samples'] if s['variant']==v)) for v in range(5)))
PY
python /app/details.py"],"timeout_ms":150000,"workdir":"/app"}

{"command":["bash","-lc","python - <<'PY'
exec(open('/app/analyze.py').read().split('for t in sorted')[0])
for t in ['algebra','number_theory','geometry','combinatorics']:
 sub=[q for q in qs if q['topic']==t]
 for kind in ['correct','noise','trap']:
  ss=[s['score'] for q in sub for s in q['samples'] if ('correct' if s['correct'] else 'trap' if s['score']>.7 else 'noise')==kind]
  print(t,kind,len(ss),np.mean(ss) if ss else 0,np.std(ss) if ss else 0)
 print('wrong repeats',[(len(s),round(np.mean(s),2)) for q in sub for a in set(s['answer'] for s in q['samples'] if not s['correct']) if len(s:=[s['score'] for s in q['samples'] if s['answer']==a])>1][:40])
PY"],"timeout_ms":150000,"workdir":"/app"}

{"command":["bash","-lc","python - <<'PY'
exec(open('/app/analyze.py').read().split('for t in sorted')[0])
for t in sorted(set(q['topic'] for q in qs)):
 print(t)
 for typ in ['easy','shared','variant','hard']:
  sub=[]
  for q in qs:
   if q['topic']!=t: continue
   high=[s for s in q['samples'] if not s['correct'] and s['score']>.7]
   ncor=sum(s['correct'] for s in q['samples'])
   cls=('shared' if len(set(s['answer'] for s in high))==1 else 'variant') if len(high)>3 else 'hard' if ncor<3 else 'easy'
   if cls==typ: sub.append(q)
  print(typ,len(sub),[round(np.mean([s['correct'] for q in sub for s in q['samples'] if s['variant']==v]),3) if sub else None for v in range(5)])
PY"],"timeout_ms":150000,"workdir":"/app"}
